import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { 
  User, Edit, LogOut, Trophy, Zap, Flame, 
  BookOpen, Award, Globe, Gamepad2 
} from "lucide-react";
import Footer from "./Footer"; // Import the footer we just made
import "../App.css";

const Profile = () => {
  const navigate = useNavigate();
  
  // Default State
  const [userData, setUserData] = useState({
    name: "Student",
    email: "student@school.edu",
    grade: "Grade 10",
    xp: 402,
    streak: 0,
    quizzes: 9,
    avgScore: "76%"
  });

  // Load Real Data
  useEffect(() => {
    const storedName = localStorage.getItem("userName");
    const storedEmail = localStorage.getItem("userEmail");
    
    if (storedName) {
      setUserData(prev => ({
        ...prev,
        name: storedName,
        email: storedEmail || "srija@gmail.com"
      }));
    }
  }, []);

  const handleSignOut = () => {
    localStorage.clear();
    navigate("/login");
  };

  return (
    <div className="profile-wrapper">
      
      {/* 1. Navbar */}
      <nav className="navbar profile-nav">
        <div className="logo" onClick={() => navigate("/")} style={{cursor:'pointer'}}>
          <Gamepad2 size={32} /> VidyaQuest
        </div>
        <div className="nav-links">
          <span onClick={() => navigate("/")}>Home</span>
          <span>Subjects</span>
          <span>Games</span>
          <span className="active-link">Leaderboard</span>
        </div>
        <div className="profile-actions">
           <button className="lang-btn"><Globe size={16}/> English</button>
           <button className="user-pill">
              <User size={16} /> {userData.name}
           </button>
        </div>
      </nav>

      {/* 2. Main Content Area */}
      <div className="profile-container">
        
        {/* --- Header Card --- */}
        <div className="profile-header-card">
          <div className="profile-banner"></div>
          <div className="profile-info-row">
            <div className="profile-avatar-box">
              <User size={64} color="#10b981" />
            </div>
            <div className="profile-text">
              <h1 className="profile-name">{userData.name}</h1>
              <p className="profile-subtext">{userData.grade} • {userData.email}</p>
            </div>
            <div className="profile-buttons">
              <button className="btn-edit"><Edit size={16} /> Edit Profile</button>
              <button className="btn-signout" onClick={handleSignOut}><LogOut size={16} /> Sign Out</button>
            </div>
          </div>
        </div>

        {/* --- Top Row: Level Progress & Badges --- */}
        <div className="dashboard-grid">
          {/* Level Progress */}
          <div className="card level-card">
             <div className="card-header">
                <Trophy color="#10b981" size={20}/> <h3>Level Progress</h3>
             </div>
             <div className="level-row">
               <div className="level-box">1</div>
               <div className="progress-container">
                  <div className="progress-meta">
                    <span>Level 1</span>
                    <span>{userData.xp} / 500 XP</span>
                  </div>
                  <div className="progress-track">
                    <div className="progress-fill" style={{width: '80%'}}></div>
                  </div>
                  <small>98 XP until Level 2</small>
               </div>
             </div>
          </div>

          {/* Badges */}
          <div className="card badges-card">
             <div className="card-header">
                <Award color="#10b981" size={20}/> <h3>Badges</h3>
             </div>
             <div className="badges-content">
                <Award size={40} color="#cbd5e1"/>
                <p>Complete quizzes to earn badges!</p>
             </div>
          </div>
        </div>

        {/* --- Stats Row --- */}
        <div className="stats-grid">
           <div className="stat-card-small">
              <Zap color="#10b981" size={28}/>
              <h2>{userData.xp}</h2>
              <span>Total XP</span>
           </div>
           <div className="stat-card-small">
              <Flame color="#f97316" size={28}/>
              <h2>{userData.streak}</h2>
              <span>Day Streak</span>
           </div>
           <div className="stat-card-small">
              <BookOpen color="#3b82f6" size={28}/>
              <h2>{userData.quizzes}</h2>
              <span>Quizzes Done</span>
           </div>
           <div className="stat-card-small">
              <Award color="#10b981" size={28}/>
              <h2>{userData.avgScore}</h2>
              <span>Avg Score</span>
           </div>
        </div>

        {/* --- Recent Activity --- */}
        <div className="card recent-activity">
           <h3>Recent Activity</h3>
           <p>You've completed {userData.quizzes} quizzes and earned {userData.xp} XP!</p>
        </div>

      </div>

      {/* 3. Footer */}
      <Footer />
    </div>
  );
};

export default Profile;
